
.protagonist-panel {
  height: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.protagonist-panel__hero {
  display: flex;
  gap: 14px;
}

.avatar-upload {
  position: relative;
  width: 80px;
  height: 80px;
  border-radius: var(--gal-radius-md);
  overflow: hidden;
  border: 2px solid transparent;
  background: linear-gradient(var(--gal-bg), var(--gal-bg)) padding-box,
    var(--gal-gradient-primary) border-box;
  cursor: pointer;
  flex-shrink: 0;

  img {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }
}

.avatar-upload__placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--gal-pink-soft);
  font-size: 30px;
  font-weight: 700;
  color: var(--gal-pink);
}

.avatar-upload__hint {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 4px;
  font-size: 11px;
  text-align: center;
  background: rgba(0, 0, 0, 0.55);
  color: #fff;
}

.protagonist-panel__info {
  flex: 1;
  min-width: 0;
}

.protagonist-panel__name {
  margin: 0 0 10px;
  font-size: 18px;
  font-weight: 800;
  background: var(--gal-gradient-primary);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.info-grid {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.info-row {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 12px;
  padding-bottom: 5px;
  border-bottom: 1px solid var(--gal-border);

  span {
    color: var(--gal-text-muted);
    flex-shrink: 0;
  }

  strong {
    text-align: right;
    word-break: break-word;
  }
}

.info-row__level {
  color: var(--gal-blue);
}

.info-row__gold {
  color: var(--gal-gold);
}

.info-row--exp {
  align-items: flex-start;
}

.info-row__exp {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;

  strong {
    font-variant-numeric: tabular-nums;
    color: var(--gal-violet);
  }
}

.exp-bar {
  width: 100%;
  max-width: 120px;
  height: 4px;
  border-radius: var(--gal-radius-pill);
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}

.exp-bar__fill {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--gal-violet), var(--gal-pink));
  transition: width 0.35s ease;
}

.stats-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.stat-card {
  text-align: center;
  padding: 14px 10px;

  i {
    display: block;
    font-size: 18px;
    margin-bottom: 6px;
    background: var(--gal-gradient-primary);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
  }
}

.stat-card__label {
  display: block;
  font-size: 10px;
  color: var(--gal-text-muted);
  letter-spacing: 0.06em;
}

.stat-card__value {
  font-size: 20px;
  font-weight: 800;
}
