
.battle-result {
  position: absolute;
  inset: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  pointer-events: auto;
}

.battle-result__backdrop {
  position: absolute;
  inset: 0;
  background: rgba(6, 9, 18, 0.82);
  backdrop-filter: blur(6px);
  pointer-events: none;
}

.battle-result__card {
  position: relative;
  z-index: 1;
  pointer-events: auto;
  width: min(100%, 360px);
  max-height: min(88%, 420px);
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 18px 16px 14px;
  text-align: center;
}

.battle-result__icon {
  width: 52px;
  height: 52px;
  margin: 0 auto 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  font-size: 22px;
  color: #fff;

  &--win {
    background: linear-gradient(135deg, #fbbf24, #f472b6);
    box-shadow: 0 8px 24px rgba(251, 191, 36, 0.35);
  }

  &--lose {
    background: linear-gradient(135deg, #64748b, #fb7185);
    box-shadow: 0 8px 24px rgba(100, 116, 139, 0.35);
  }
}

.battle-result__title {
  margin: 0;
  font-size: 20px;
  font-weight: 800;
  background: var(--gal-gradient-primary);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.battle-result__subtitle {
  margin: 0;
  font-size: 12px;
  color: var(--gal-text-muted);
}

.battle-result__hp,
.battle-result__sheet-hp {
  margin: 0;
  font-size: 12px;
  color: var(--gal-text-muted);

  strong {
    color: var(--gal-blue);
    font-variant-numeric: tabular-nums;
  }

  span {
    font-size: 11px;
  }
}

.battle-result__sheet-hp {
  font-size: 11px;
  opacity: 0.85;
}

.battle-result__log {
  flex: 1;
  min-height: 80px;
  max-height: 180px;
  overflow-y: auto;
  text-align: left;
  padding: 8px 10px;
  border-radius: var(--gal-radius-sm);
  background: rgba(0, 0, 0, 0.28);
  border: 1px solid var(--gal-border);

  p {
    margin: 0 0 4px;
    font-size: 10px;
    line-height: 1.45;
    color: var(--gal-text-muted);

    &:last-child {
      margin-bottom: 0;
    }
  }
}

.battle-result__actions {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 4px;

  &--defeat {
    flex-direction: row;
    flex-wrap: wrap;
  }
}

.battle-result__btn {
  flex: 1;
  min-width: 0;
  justify-content: center;

  &--retry {
    flex: 0 0 38%;
    background: rgba(255, 255, 255, 0.08);
    border: 1px solid var(--gal-border);
    color: var(--gal-text);

    &:hover:not(:disabled) {
      background: rgba(255, 255, 255, 0.12);
    }
  }
}
