
.dialogue-panel {
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  --dialogue-portrait-w: v-bind(css_portrait_w);
  --dialogue-portrait-h: v-bind(css_portrait_h);
  --dialogue-body-h: v-bind(css_body_h);
}

.dialogue-panel__label {
  width: 100%;
}

.dialogue-panel__label-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
}

.dialogue-panel__mode-btn {
  padding: 3px 10px;
  font-size: 10px;
  letter-spacing: 0.06em;
  color: var(--gal-text-muted);
  border-color: transparent;
  background: rgba(255, 255, 255, 0.04);

  i {
    font-size: 9px;
  }

  &--active {
    color: #fff;
    border-color: transparent;
    background: var(--gal-gradient-primary);
    box-shadow: 0 4px 14px rgba(99, 102, 241, 0.28);
  }
}

.dialogue-panel__progress {
  text-transform: none;
  letter-spacing: 0;
  font-variant-numeric: tabular-nums;
  font-size: 10px;
  padding: 2px 8px;
  border-radius: var(--gal-radius-pill);
  background: var(--gal-blue-soft);
  color: var(--gal-blue);

  &::before {
    display: none;
  }
}

.dialogue-panel__body {
  position: relative;
  box-sizing: border-box;
  height: var(--dialogue-body-h);
  min-height: var(--dialogue-body-h);
  max-height: var(--dialogue-body-h);
  padding: 12px;
  border-radius: var(--gal-radius-md);
  border: 1px solid var(--gal-border);
  background: var(--gal-gradient-card);
  backdrop-filter: blur(8px);
  transition: border-color var(--gal-transition);
  user-select: none;
  overflow: hidden;

  &:hover {
    border-color: rgba(96, 165, 250, 0.35);

    .dialogue-panel__center-line {
      opacity: 0.35;
    }

    .dialogue-panel__stage::before,
    .dialogue-panel__stage::after {
      opacity: 1;
    }
  }
}

.dialogue-panel__stage {
  position: relative;
  height: 100%;
  cursor: pointer;

  &::before,
  &::after {
    content: '';
    position: absolute;
    top: 0;
    bottom: 0;
    width: 50%;
    opacity: 0;
    transition: opacity var(--gal-transition);
    pointer-events: none;
    z-index: 1;
  }

  &::before {
    left: 0;
    background: linear-gradient(90deg, rgba(96, 165, 250, 0.08) 0%, transparent 100%);
  }

  &::after {
    right: 0;
    background: linear-gradient(270deg, rgba(244, 114, 182, 0.08) 0%, transparent 100%);
  }
}

.dialogue-panel__center-line {
  position: absolute;
  top: 8%;
  bottom: 8%;
  left: 50%;
  width: 1px;
  transform: translateX(-50%);
  background: linear-gradient(
    180deg,
    transparent 0%,
    rgba(96, 165, 250, 0.55) 35%,
    rgba(244, 114, 182, 0.55) 65%,
    transparent 100%
  );
  opacity: 0;
  transition: opacity var(--gal-transition);
  pointer-events: none;
  z-index: 1;
}

.dialogue-bubble {
  position: relative;
  z-index: 2;
  display: flex;
  gap: 12px;
  align-items: stretch;
  height: var(--dialogue-portrait-h);
  min-height: var(--dialogue-portrait-h);
  max-height: var(--dialogue-portrait-h);
}

.dialogue-bubble--no-portrait {
  .dialogue-bubble__content {
    flex: 1;
    width: 100%;
  }
}

.dialogue-bubble--narrator .dialogue-bubble__content {
  background: rgba(148, 163, 184, 0.08);
  border-style: dashed;
}

.dialogue-bubble__portrait {
  flex-shrink: 0;
  width: var(--dialogue-portrait-w);
  height: var(--dialogue-portrait-h);
  aspect-ratio: v-bind(PORTRAIT_ASPECT);
  border-radius: var(--gal-radius-sm);
  overflow: hidden;
  border: 2px solid transparent;
  background: linear-gradient(var(--gal-bg), var(--gal-bg)) padding-box,
    var(--gal-gradient-primary) border-box;

  :deep(.media-view) {
    object-fit: contain;
    background: var(--gal-bg);
  }
}

.dialogue-bubble__portrait--text {
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--gal-pink-soft);
  color: var(--gal-pink);
  font-weight: 700;
  font-size: 28px;
}

.dialogue-bubble__content {
  flex: 1;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  padding: 10px 12px;
  border-radius: var(--gal-radius-md);
  background: rgba(15, 20, 38, 0.65);
  border: 1px solid var(--gal-border);
  overflow: hidden;
}

.dialogue-bubble__name {
  flex-shrink: 0;
  margin-bottom: 6px;
  line-height: 1.2;
  min-height: 1.2em;
}

.dialogue-bubble__name-text {
  display: inline-block;
  font-size: 11px;
  font-weight: 700;
}

.dialogue-bubble__name--character .dialogue-bubble__name-text {
  background: linear-gradient(
    90deg,
    #f8fafc 0%,
    var(--gal-pink) 28%,
    var(--gal-violet) 52%,
    var(--gal-blue) 72%,
    #f8fafc 100%
  );
  background-size: 220% auto;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation:
    dialogue-name-shimmer 3.6s linear infinite,
    dialogue-name-enter 0.45s ease-out;
  filter: drop-shadow(0 0 8px rgba(244, 114, 182, 0.35));
}

.dialogue-bubble__name--narrator .dialogue-bubble__name-text {
  color: var(--gal-text-muted);
  font-weight: 600;
  letter-spacing: 0.12em;
}

.dialogue-bubble__name--other .dialogue-bubble__name-text {
  color: var(--gal-violet);
  animation: dialogue-name-enter 0.45s ease-out;
}

.dialogue-bubble__text-wrap {
  flex: 1;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  cursor: auto;
}

.dialogue-bubble__text {
  font-size: 13px;
  line-height: 1.55;
  color: var(--gal-text);
  word-break: break-word;
}

.dialogue-panel__empty {
  height: 100%;
  min-height: 0;
  padding: 0;
  justify-content: center;
}

@keyframes dialogue-name-shimmer {
  0% {
    background-position: 220% center;
  }

  100% {
    background-position: -220% center;
  }
}

@keyframes dialogue-name-enter {
  0% {
    opacity: 0;
    transform: translateY(4px) scale(0.96);
  }

  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}
