
.inventory-panel {
  min-height: 0;
  overflow-y: auto;
}

.inventory-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.inventory-item__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 6px;
}

.inventory-item__name {
  font-weight: 700;
  font-size: 14px;
  color: var(--gal-text);
}

.inventory-item__desc {
  font-size: 12px;
  color: var(--gal-text-muted);
  line-height: 1.5;
}
