
.battle-dock {
  height: 100%;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 6px 8px;
  background: linear-gradient(180deg, rgba(12, 18, 34, 0.98) 0%, rgba(8, 12, 24, 0.95) 100%);
  overflow: hidden;
}

.battle-dock--encounter {
  gap: 5px;
}

.battle-dock__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  flex-shrink: 0;
  min-height: 18px;
}

.battle-dock__title {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--gal-text-muted);

  i {
    margin-right: 3px;
    color: var(--gal-pink);
  }
}

.battle-dock__hp-tag {
  font-size: 9px;
  color: var(--gal-text-muted);
  font-variant-numeric: tabular-nums;

  i {
    margin-right: 3px;
    color: var(--gal-pink);
    font-size: 8px;
  }
}

.battle-dock__flee {
  padding: 1px 8px;
  font-size: 9px;
}

.battle-dock__encounter {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
  justify-content: space-between;
}

.battle-dock__encounter-top {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-height: 0;
}

.battle-dock__encounter-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}

.battle-dock__boss-name {
  font-size: 13px;
  line-height: 1.2;
  color: var(--gal-pink);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.battle-dock__encounter-desc {
  margin: 0;
  font-size: 10px;
  line-height: 1.35;
  color: var(--gal-text);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.battle-dock__boss-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2px;
  font-size: 9px;
  color: var(--gal-text-muted);

  span {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 2px;
    padding: 2px 0;
    border-radius: 4px;
    background: rgba(255, 255, 255, 0.04);
  }

  i {
    font-size: 8px;
    color: var(--gal-blue);
  }
}

.battle-dock__encounter-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5px;
  flex-shrink: 0;

  .gal-btn {
    justify-content: center;
    min-height: 28px;
    font-size: 11px;
    font-weight: 700;
  }
}

.battle-dock__encounter-dice {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 52px;
  pointer-events: none;
}

.battle-dock__idle {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 72px;
}

.battle-dock__result-hint {
  flex: 1;
  margin: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 0 6px;
  font-size: 10px;
  line-height: 1.4;
  color: var(--gal-text-muted);
}

.battle-dock__hp {
  display: flex;
  flex-direction: column;
  gap: 3px;
  flex-shrink: 0;
}

.hp-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 1.2fr auto;
  align-items: center;
  gap: 4px;
  font-size: 9px;

  span {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: var(--gal-text-muted);
    font-weight: 700;
  }

  strong {
    font-size: 9px;
    font-variant-numeric: tabular-nums;
  }
}

.hp-bar {
  height: 4px;
  border-radius: var(--gal-radius-pill);
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}

.hp-bar__fill {
  height: 100%;
  border-radius: inherit;
  transition: width 0.35s ease;

  &--player {
    background: linear-gradient(90deg, var(--gal-blue), var(--gal-violet));
  }

  &--enemy {
    background: linear-gradient(90deg, var(--gal-pink-deep), var(--gal-danger));
  }
}

.battle-dock__pick {
  flex-shrink: 0;
}

.battle-dock__pick-row {
  display: flex;
  align-items: center;
  gap: 4px;
}

.battle-dock__hint {
  flex-shrink: 0;
  font-size: 9px;
  color: var(--gal-text-muted);
  font-weight: 700;
}

.battle-dock__counts {
  display: flex;
  flex: 1;
  gap: 3px;
}

.battle-dock__count {
  flex: 1;
  padding: 4px 0;
  font-size: 10px;
  font-weight: 700;

  &--active {
    border-color: transparent;
    background: var(--gal-gradient-primary);
    color: #fff;
  }
}

.battle-dock__roll {
  flex-shrink: 0;
  width: 32px;
  min-width: 32px;
  padding: 4px 0;
  font-size: 11px;
}

.battle-dock__dice-result {
  display: flex;
  flex-direction: column;
  gap: 3px;
  flex-shrink: 0;
}

.dice-line {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 1.2fr auto;
  align-items: center;
  gap: 3px;
  font-size: 9px;

  span {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: var(--gal-text-muted);
    font-weight: 700;
  }

  em {
    font-style: normal;
    font-weight: 700;
    color: var(--gal-gold);
  }
}

.dice-group {
  display: flex;
  flex-wrap: wrap;
  gap: 2px;
}

.dice-face {
  width: 18px;
  height: 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
  font-size: 10px;
  font-weight: 800;
  border: 1px solid var(--gal-border);

  &--player {
    background: var(--gal-blue-soft);
    color: var(--gal-blue);
  }

  &--enemy {
    background: var(--gal-pink-soft);
    color: var(--gal-pink);
  }

  &--rolling {
    animation: dice-wobble 0.45s ease-in-out infinite;
  }
}

.battle-dock__initiative {
  margin: 0;
  font-size: 9px;
  color: var(--gal-violet);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.battle-dock__strike-hint {
  margin: 0;
  font-size: 9px;
  color: var(--gal-blue);
}

.battle-dock__log {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 4px 6px;
  border-radius: var(--gal-radius-sm);
  background: rgba(0, 0, 0, 0.25);
  border: 1px solid var(--gal-border);

  p {
    margin: 0 0 2px;
    font-size: 9px;
    line-height: 1.35;
    color: var(--gal-text-muted);

    &:last-child {
      margin-bottom: 0;
      color: var(--gal-text);
    }
  }
}

@keyframes dice-wobble {
  0%,
  100% {
    transform: rotate(-6deg) scale(1);
  }

  50% {
    transform: rotate(6deg) scale(1.06);
  }
}
