
.input-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
  position: relative;
  z-index: 2;
}

.input-panel__label {
  width: 100%;
}

.input-panel__sending {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 10px;
  letter-spacing: 0;
  text-transform: none;
  color: var(--gal-pink);

  &::before {
    display: none;
  }
}

.input-panel__hint {
  margin: 0;
  padding: 8px 10px;
  font-size: 11px;
  line-height: 1.45;
  color: var(--gal-text-muted);
  border: 1px dashed var(--gal-border);
  border-radius: var(--gal-radius-sm);
  background: var(--gal-glass);
}

.input-panel__wild {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.input-panel__wild-desc {
  margin: 0;
  font-size: 11px;
  line-height: 1.5;
  color: var(--gal-text-muted);
  text-align: center;
}

.input-panel__summarize {
  width: 100%;
  justify-content: center;
  min-height: 42px;
  font-size: 13px;
  font-weight: 700;
}

.input-panel__row {
  display: flex;
  gap: 8px;
  flex-shrink: 0;
}

.input-panel__wrap {
  flex: 1;
  min-width: 0;
  padding: 1px;
  border-radius: var(--gal-radius-pill);
  background: var(--gal-gradient-input);
}

.input-panel__input {
  width: 100%;
  padding: 10px 14px;
  border-radius: var(--gal-radius-pill);
  border: none;
  background: rgba(10, 14, 26, 0.92);
  color: var(--gal-text);
  font-size: 13px;
  font-family: inherit;

  &:focus {
    outline: none;
  }

  &::placeholder {
    color: var(--gal-text-muted);
  }

  &:disabled {
    opacity: 0.6;
  }
}

.input-panel__regenerate {
  flex-shrink: 0;
  min-width: 42px;
  min-height: 42px;
  padding: 0 12px;
  color: var(--gal-violet);
  border-color: rgba(139, 92, 246, 0.35);

  &:hover:not(:disabled) {
    color: #c4b5fd;
    border-color: rgba(139, 92, 246, 0.55);
    background: rgba(139, 92, 246, 0.12);
  }

  &:disabled {
    opacity: 0.45;
  }
}

.input-panel__send {
  flex-shrink: 0;
}
