
.gallery-panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-height: 0;
  overflow-y: auto;
}

.gallery-tabs {
  flex-shrink: 0;
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 4px;
}

.gallery-toolbar {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11px;
  color: var(--gal-text-muted);
}

.gallery-toolbar__unlock {
  font-size: 10px;
  color: var(--gal-gold);
  border-color: rgba(252, 211, 77, 0.35);
  background: rgba(252, 211, 77, 0.1);
}

.gallery-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.gallery-card__media {
  width: 100%;
  aspect-ratio: v-bind(SCENE_ASPECT);
  border-radius: var(--gal-radius-sm);
  overflow: hidden;
  border: 1px solid var(--gal-border);
  background: rgba(6, 10, 20, 0.85);
  transition: border-color var(--gal-transition);
}

.gallery-card:not(.gallery-card--locked) .gallery-card__media:hover {
  border-color: rgba(244, 114, 182, 0.45);
}

.gallery-card--locked .gallery-card__media {
  border-style: dashed;
  opacity: 0.85;
}

.gallery-card__locked {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gal-text-muted);
  background: var(--gal-glass);

  i {
    font-size: 22px;
    opacity: 0.6;
  }
}

.gallery-card__label {
  margin: 6px 0 0;
  font-size: 10px;
  line-height: 1.35;
  color: var(--gal-text-muted);
  text-align: center;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.gallery-card--locked .gallery-card__label {
  opacity: 0.7;
}
