
.chat-panel {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  margin: -12px;
  overflow: hidden;
  background: var(--gal-gradient-bg);
}

.chat-panel__glow {
  position: absolute;
  border-radius: 50%;
  filter: blur(64px);
  pointer-events: none;
  opacity: 0.55;

  &--pink {
    width: 180px;
    height: 180px;
    top: -40px;
    right: -20px;
    background: rgba(244, 114, 182, 0.35);
  }

  &--blue {
    width: 200px;
    height: 200px;
    bottom: 60px;
    left: -60px;
    background: rgba(96, 165, 250, 0.28);
  }
}

.chat-panel__header {
  position: relative;
  z-index: 1;
  flex-shrink: 0;
  display: grid;
  grid-template-columns: 36px 1fr 36px;
  align-items: center;
  gap: 8px;
  padding: 12px 14px;
  border-bottom: 1px solid var(--gal-border);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.08) 0%, rgba(255, 255, 255, 0.02) 100%);
  backdrop-filter: blur(12px);
}

.chat-panel__header-spacer {
  width: 36px;
}

.chat-panel__back {
  width: 36px;
  height: 36px;
  border: 1px solid var(--gal-border);
  border-radius: 12px;
  background: var(--gal-glass);
  color: #e2e8f0;
  cursor: pointer;
  transition:
    border-color 0.2s,
    background 0.2s,
    transform 0.15s;

  &:hover {
    border-color: rgba(244, 114, 182, 0.45);
    background: rgba(244, 114, 182, 0.12);
    transform: translateX(-1px);
  }
}

.chat-panel__title-wrap {
  min-width: 0;
  text-align: center;
}

.chat-panel__name {
  min-width: 0;
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 0.4px;
  color: #f8fafc;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-height: 1.35em;
}

.chat-panel__name--idle {
  background: linear-gradient(90deg, #f8fafc 0%, var(--gal-pink) 40%, var(--gal-blue) 60%, #f8fafc 100%);
  background-size: 220% auto;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: chat-name-shimmer 4s linear infinite;
}

.chat-panel__subtitle {
  display: block;
  margin-top: 2px;
  font-size: 9px;
  letter-spacing: 0.22em;
  color: rgba(226, 232, 240, 0.45);
}

@keyframes chat-name-shimmer {
  0% {
    background-position: 220% center;
  }

  100% {
    background-position: -220% center;
  }
}

.chat-panel__messages {
  position: relative;
  z-index: 1;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 16px 14px;
  display: flex;
  flex-direction: column;
  gap: 14px;

  &::-webkit-scrollbar {
    width: 5px;
  }

  &::-webkit-scrollbar-thumb {
    border-radius: 999px;
    background: linear-gradient(var(--gal-pink), var(--gal-blue));
  }
}

.chat-panel__empty {
  margin: auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  color: rgba(226, 232, 240, 0.45);
  font-size: 12px;

  i {
    font-size: 28px;
    background: linear-gradient(135deg, var(--gal-pink), var(--gal-blue));
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
  }
}

.chat-message {
  display: flex;
  align-items: center;
  gap: 10px;
  max-width: 100%;

  &--user {
    flex-direction: row;
    justify-content: flex-end;

    .chat-message__bubble {
      background: linear-gradient(135deg, var(--gal-pink-deep) 0%, var(--gal-pink) 55%, #fb7185 100%);
      color: #fff;
      border: 1px solid rgba(255, 255, 255, 0.2);
      border-bottom-right-radius: 6px;
      box-shadow: 0 8px 24px rgba(236, 72, 153, 0.28);
    }
  }

  &--active .chat-message__bubble--clickable {
    box-shadow:
      0 8px 24px rgba(236, 72, 153, 0.35),
      0 0 0 2px rgba(255, 255, 255, 0.35);
  }

  &--editing {
    align-items: center;
  }

  &--npc {
    flex-direction: row;
    justify-content: flex-start;

    .chat-message__bubble {
      max-width: calc(100% - 54px);
      background: linear-gradient(145deg, rgba(96, 165, 250, 0.22) 0%, rgba(167, 139, 250, 0.16) 100%);
      border: 1px solid rgba(147, 197, 253, 0.28);
      border-bottom-left-radius: 6px;
      box-shadow: 0 8px 22px rgba(59, 130, 246, 0.12);
      backdrop-filter: blur(8px);
    }
  }

  &--system {
    justify-content: center;

    .chat-message__bubble {
      background: rgba(255, 255, 255, 0.04);
      color: rgba(226, 232, 240, 0.55);
      font-size: 10px;
      padding: 5px 12px;
      border: 1px dashed rgba(255, 255, 255, 0.12);
      border-radius: 999px;
      max-width: 100%;
    }
  }

  &--typing .chat-message__bubble {
    min-width: 88px;
  }
}

.chat-message__avatar {
  flex-shrink: 0;
  align-self: center;
}

.chat-message__user-col {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
  max-width: calc(100% - 54px);

  .chat-message__bubble {
    max-width: 100%;
  }
}

.chat-message__bubble--clickable {
  cursor: pointer;
  transition:
    transform 0.15s,
    box-shadow 0.2s;

  &:hover {
    transform: translateY(-1px);
    box-shadow: 0 10px 28px rgba(236, 72, 153, 0.38);
  }
}

.chat-message__menu {
  display: flex;
  gap: 6px;
  padding: 4px;
  border-radius: 12px;
  border: 1px solid var(--gal-border);
  background: rgba(15, 20, 38, 0.92);
  backdrop-filter: blur(10px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.25);
}

.chat-message__menu-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 10px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: #e2e8f0;
  font-size: 11px;
  font-family: inherit;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s;

  i {
    font-size: 10px;
    opacity: 0.85;
  }

  &:hover:not(:disabled) {
    background: rgba(244, 114, 182, 0.18);
  }

  &:disabled {
    opacity: 0.45;
    cursor: not-allowed;
  }
}

.chat-message__edit-wrap {
  width: 100%;
  min-width: 180px;
  padding: 8px;
  border-radius: 14px;
  border: 1px solid rgba(244, 114, 182, 0.45);
  background: rgba(15, 20, 38, 0.95);
  box-shadow: 0 8px 24px rgba(236, 72, 153, 0.2);
}

.chat-message__edit-input {
  width: 100%;
  min-height: 52px;
  padding: 8px 10px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.04);
  color: #f8fafc;
  font-size: 13px;
  line-height: 1.5;
  font-family: inherit;
  resize: vertical;

  &:focus {
    outline: none;
    border-color: rgba(244, 114, 182, 0.5);
  }

  &:disabled {
    opacity: 0.65;
  }
}

.chat-message__edit-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 8px;
}

.chat-message__action {
  padding: 5px 10px;
  border-radius: 8px;
  border: 1px solid transparent;
  font-size: 11px;
  font-family: inherit;
  cursor: pointer;

  &--ghost {
    background: transparent;
    border-color: rgba(255, 255, 255, 0.15);
    color: rgba(226, 232, 240, 0.75);

    &:hover {
      background: rgba(255, 255, 255, 0.06);
    }
  }

  &--primary {
    background: var(--gal-gradient-primary);
    color: #fff;
    border: none;

    &:disabled {
      opacity: 0.5;
      cursor: not-allowed;
    }
  }
}

.chat-message__bubble {
  max-width: calc(100% - 54px);
  padding: 10px 14px;
  border-radius: 16px;
  font-size: 13px;
  line-height: 1.5;
  word-break: break-word;
  color: #f1f5f9;
}

.chat-message__bubble--typing {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 12px 14px;
}

.typing-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: linear-gradient(180deg, var(--gal-blue) 0%, var(--gal-violet) 100%);
}

.typing-label {
  margin-left: 6px;
  font-size: 11px;
  color: rgba(226, 232, 240, 0.55);
  white-space: nowrap;
}

.chat-panel__composer {
  position: relative;
  z-index: 1;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 14px 14px;
  border-top: 1px solid var(--gal-border);
  background: linear-gradient(0deg, rgba(12, 18, 34, 0.95) 0%, rgba(255, 255, 255, 0.04) 100%);
  backdrop-filter: blur(14px);
}

.chat-panel__input-wrap {
  flex: 1;
  min-width: 0;
  padding: 1px;
  border-radius: 999px;
  background: var(--gal-gradient-input);
}

.chat-panel__input {
  width: 100%;
  padding: 10px 16px;
  border-radius: 999px;
  border: none;
  background: rgba(15, 20, 38, 0.92);
  color: #f8fafc;
  font-size: 13px;
  font-family: inherit;

  &::placeholder {
    color: rgba(226, 232, 240, 0.38);
  }

  &:focus {
    outline: none;
  }

  &:disabled {
    opacity: 0.65;
    cursor: wait;
  }
}

.chat-panel__send {
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  border: none;
  border-radius: 14px;
  background: var(--gal-gradient-primary);
  color: #fff;
  font-size: 15px;
  cursor: pointer;
  box-shadow: 0 8px 22px rgba(99, 102, 241, 0.35);
  transition:
    transform 0.15s,
    box-shadow 0.2s,
    opacity 0.2s;

  &:hover:not(:disabled) {
    transform: translateY(-1px);
    box-shadow: 0 10px 28px rgba(236, 72, 153, 0.35);
  }

  &:disabled {
    opacity: 0.55;
    cursor: not-allowed;
    box-shadow: none;
  }
}
